// frontend/src/components/GraphView.jsx  (REPLACE)

import React, { useRef, useCallback } from "react";
import ForceGraph2D from "react-force-graph-2d";

export default function GraphView({ cycles }) {
  const graphRef = useRef();

  if (!cycles || cycles.length === 0) {
    return (
      <div style={{ background: "#1e293b", borderRadius: "12px", padding: "40px", textAlign: "center", color: "#64748b" }}>
        No fraud cycles detected yet. Insert trades to trigger detection.
      </div>
    );
  }

  // Build graph data from all cycles
  const nodesMap = {};
  const linksArr = [];
  const cycleEdges = new Set(); // track which edges are part of a closing loop

  cycles.forEach((c, cycleIdx) => {
    const cycle = c.cycle; // e.g. [1, 2, 3, 1]

    cycle.forEach((traderId) => {
      if (!nodesMap[traderId]) {
        nodesMap[traderId] = {
          id:         traderId,
          label:      `T-${traderId}`,
          risk:       c.risk_label,
          trust:      c.trust_score,
          confidence: c.confidence,
          cycleIdx
        };
      }
    });

    // Draw edges: A→B→C→A (including closing edge back to origin)
    for (let i = 0; i < cycle.length - 1; i++) {
      const src = cycle[i];
      const tgt = cycle[i + 1];
      const isClosingEdge = (i === cycle.length - 2) && (tgt === cycle[0]);
      const edgeKey = `${src}-${tgt}`;

      if (isClosingEdge) cycleEdges.add(edgeKey);

      linksArr.push({
        source:        src,
        target:        tgt,
        isCycle:       true,
        isClosingEdge, // the final A→A closing arrow
        confidence:    c.confidence
      });
    }
  });

  const graphData = {
    nodes: Object.values(nodesMap),
    links: linksArr
  };

  const getNodeColor = (node) => {
    if (node.risk === "HIGH")   return "#ef4444";
    if (node.risk === "MEDIUM") return "#f97316";
    return "#22c55e";
  };

  const getLinkColor = (link) => {
    if (link.isClosingEdge)     return "#a855f7"; // purple = loop closure
    if (link.confidence >= 60)  return "#ef4444"; // red = high risk
    if (link.confidence >= 30)  return "#f97316"; // orange = medium
    return "#22c55e";
  };

  const drawNode = useCallback((node, ctx, globalScale) => {
    const radius    = 8;
    const fontSize  = Math.max(10 / globalScale, 4);
    const color     = getNodeColor(node);

    // Outer glow ring for high-risk nodes
    if (node.risk === "HIGH") {
      ctx.beginPath();
      ctx.arc(node.x, node.y, radius + 4, 0, 2 * Math.PI);
      ctx.fillStyle = "rgba(239,68,68,0.15)";
      ctx.fill();
    }

    // Node circle
    ctx.beginPath();
    ctx.arc(node.x, node.y, radius, 0, 2 * Math.PI);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.strokeStyle = "#0f172a";
    ctx.lineWidth = 2;
    ctx.stroke();

    // Label
    ctx.font        = `bold ${fontSize}px monospace`;
    ctx.fillStyle   = "#ffffff";
    ctx.textAlign   = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(`T-${node.id}`, node.x, node.y);
  }, []);

  return (
    <div>
      {/* Legend */}
      <div style={{ display: "flex", gap: "20px", marginBottom: "12px", flexWrap: "wrap", fontSize: "0.8rem" }}>
        {[
          { color: "#ef4444", label: "High Risk Node"    },
          { color: "#f97316", label: "Medium Risk Node"  },
          { color: "#22c55e", label: "Low Risk Node"     },
          { color: "#a855f7", label: "Loop Closing Edge" },
          { color: "#ef4444", label: "High Risk Edge"    },
        ].map((l) => (
          <div key={l.label} style={{ display: "flex", alignItems: "center", gap: "6px" }}>
            <div style={{ width: "12px", height: "12px", borderRadius: "50%", background: l.color }} />
            <span style={{ color: "#94a3b8" }}>{l.label}</span>
          </div>
        ))}
      </div>

      {/* Graph canvas */}
      <div style={{ background: "#0f172a", borderRadius: "12px", overflow: "hidden", height: "520px" }}>
        <ForceGraph2D
          ref={graphRef}
          graphData={graphData}
          nodeLabel={(node) =>
            `Trader ${node.id}\nTrust: ${node.trust} | Risk: ${node.risk}\nConfidence: ${node.confidence}%`
          }
          nodeCanvasObject={drawNode}
          nodeCanvasObjectMode={() => "replace"}
          linkColor={getLinkColor}
          linkWidth={(link) => link.isClosingEdge ? 3 : 1.5}
          linkDirectionalArrowLength={8}
          linkDirectionalArrowRelPos={1}
          linkDirectionalParticles={(link) => link.isClosingEdge ? 4 : 0}
          linkDirectionalParticleSpeed={0.005}
          linkDirectionalParticleColor={() => "#a855f7"}
          cooldownTicks={120}
          onEngineStop={() => graphRef.current?.zoomToFit(500, 60)}
          backgroundColor="#0f172a"
        />
      </div>

      <p style={{ color: "#64748b", fontSize: "0.8rem", marginTop: "8px" }}>
        💜 Purple animated edge = loop closure (A→B→C→<strong style={{color:"#a855f7"}}>A</strong>) &nbsp;·&nbsp;
        Hover nodes for details &nbsp;·&nbsp; Scroll to zoom
      </p>
    </div>
  );
}
